import { ChevronDown, Monitor, PanelLeft, PanelRight } from 'lucide-react';
import { useId, useState, type HTMLAttributes, type ReactNode, type Ref } from 'react';
import { cn } from '../../utils/cn';
import { IconButton } from '../../ui/button';
import { SkipLink } from '../../ui/visually-hidden';
import { useI18n } from '../../i18n/I18nProvider';
import { canvasLayoutVariants } from './canvas-layout.variants';

/** Controlled-or-uncontrolled boolean (open state of a panel). */
function usePanelState(value: boolean | undefined, defaultValue: boolean, onChange?: (open: boolean) => void) {
  const [inner, setInner] = useState(defaultValue);
  const open = value ?? inner;
  const set = (next: boolean) => {
    if (value === undefined) setInner(next);
    onChange?.(next);
  };
  return [open, set] as const;
}

export interface CanvasLayoutProps extends Omit<HTMLAttributes<HTMLDivElement>, 'className' | 'children'> {
  className?: string;
  ref?: Ref<HTMLDivElement>;
  /** The full-bleed canvas (a flow editor, a code editor, a map…). Rendered inside `<main>`. */
  children?: ReactNode;
  /** Top bar content (title, breadcrumb, run/save actions). The panel toggles sit on its right. */
  header?: ReactNode;
  /** Floating toolbar centred over the canvas (large screens). */
  toolbar?: ReactNode;
  /** Left palette (node/shape library). */
  palette?: ReactNode;
  paletteLabel?: string;
  paletteOpen?: boolean;
  defaultPaletteOpen?: boolean;
  onPaletteOpenChange?: (open: boolean) => void;
  /** Right inspector (properties of the selection). */
  inspector?: ReactNode;
  inspectorLabel?: string;
  inspectorOpen?: boolean;
  defaultInspectorOpen?: boolean;
  onInspectorOpenChange?: (open: boolean) => void;
  /** Bottom console (logs, problems, run output). Collapsible from its own bar. */
  console?: ReactNode;
  consoleLabel?: string;
  /** Extra controls on the right of the console bar (clear, filter…). */
  consoleActions?: ReactNode;
  consoleOpen?: boolean;
  defaultConsoleOpen?: boolean;
  onConsoleOpenChange?: (open: boolean) => void;
  /** Shown over the canvas below `lg`, where palette and inspector are hidden. Pass `null` to hide. */
  smallScreenNotice?: ReactNode;
  /**
   * Inside an app shell that already owns <main> and the skip link (SidebarLayout, StackedLayout):
   * render the content region as a plain <div> and drop this layout's skip link.
   */
  embedded?: boolean;
  /** `id` of the `<main>` landmark (skip-link target). */
  mainId?: string;
  /** Accessible name of the canvas region. */
  mainLabel?: string;
  skipLinkLabel?: string;
  /** Fill the viewport (`h-dvh`) instead of the container. */
  fullScreen?: boolean;
}

/**
 * Editor shell for a full-bleed canvas: top bar · left palette · canvas with a floating toolbar ·
 * right inspector · collapsible bottom console. Palette and inspector toggle from the top bar
 * (aria-expanded). Below `lg` the side panels hide and a read-only notice shows over the canvas.
 */
export function CanvasLayout({
  children,
  header,
  toolbar,
  palette,
  paletteLabel: paletteLabelProp,
  paletteOpen: paletteOpenProp,
  defaultPaletteOpen = true,
  onPaletteOpenChange,
  inspector,
  inspectorLabel: inspectorLabelProp,
  inspectorOpen: inspectorOpenProp,
  defaultInspectorOpen = true,
  onInspectorOpenChange,
  console: consoleContent,
  consoleLabel: consoleLabelProp,
  consoleActions,
  consoleOpen: consoleOpenProp,
  defaultConsoleOpen = true,
  onConsoleOpenChange,
  smallScreenNotice: smallScreenNoticeProp,
  embedded = false,
  mainId = 'main',
  mainLabel: mainLabelProp,
  skipLinkLabel: skipLinkLabelProp,
  fullScreen = false,
  className,
  ...props
}: CanvasLayoutProps) {
  const { t } = useI18n();
  const paletteLabel = paletteLabelProp ?? t('canvas.palette');
  const inspectorLabel = inspectorLabelProp ?? t('canvas.inspector');
  const consoleLabel = consoleLabelProp ?? t('canvas.console');
  const smallScreenNotice = smallScreenNoticeProp ?? t('canvas.smallScreen');
  const mainLabel = mainLabelProp ?? t('canvas.main');
  const skipLinkLabel = skipLinkLabelProp ?? t('skip.canvas');
  const MainTag = embedded ? 'div' : 'main';
  const [paletteOpen, setPaletteOpen] = usePanelState(paletteOpenProp, defaultPaletteOpen, onPaletteOpenChange);
  const [inspectorOpen, setInspectorOpen] = usePanelState(inspectorOpenProp, defaultInspectorOpen, onInspectorOpenChange);
  const [consoleOpen, setConsoleOpen] = usePanelState(consoleOpenProp, defaultConsoleOpen, onConsoleOpenChange);
  const uid = useId();
  const paletteId = `${uid}-palette`;
  const inspectorId = `${uid}-inspector`;
  const consoleBodyId = `${uid}-console`;
  const s = canvasLayoutVariants({ fullScreen, consoleOpen });

  return (
    <div className={cn(s.root(), className)} {...props}>
      {!embedded && (
        <SkipLink targetId={mainId} className={s.skipLink()}>
          {skipLinkLabel}
        </SkipLink>
      )}
      <header className={s.header()}>
        <div className={s.headerContent()}>{header}</div>
        {(palette != null || inspector != null) && (
          <div className={s.toggles()}>
            {palette != null && (
              <IconButton
                icon={PanelLeft}
                size="sm"
                label={paletteLabel}
                aria-expanded={paletteOpen}
                aria-controls={paletteId}
                onClick={() => setPaletteOpen(!paletteOpen)}
              />
            )}
            {inspector != null && (
              <IconButton
                icon={PanelRight}
                size="sm"
                label={inspectorLabel}
                aria-expanded={inspectorOpen}
                aria-controls={inspectorId}
                onClick={() => setInspectorOpen(!inspectorOpen)}
              />
            )}
          </div>
        )}
      </header>
      <div className={s.body()}>
        {palette != null && (
          <aside id={paletteId} aria-label={paletteLabel} hidden={!paletteOpen} className={s.palette()}>
            <div className={s.panelTitle()} aria-hidden>
              {paletteLabel}
            </div>
            <div className={s.panelBody()}>{palette}</div>
          </aside>
        )}
        <div className={s.center()}>
          <MainTag id={mainId} tabIndex={-1} role={embedded ? 'region' : undefined} aria-label={mainLabel} className={s.main()}>
            {smallScreenNotice != null && (
              <p className={s.notice()}>
                <Monitor size={14} aria-hidden className="shrink-0" />
                {smallScreenNotice}
              </p>
            )}
            {toolbar != null && <div className={s.toolbar()}>{toolbar}</div>}
            {children}
          </MainTag>
          {consoleContent != null && (
            <section aria-label={consoleLabel} className={s.console()}>
              <div className={s.consoleBar()}>
                <button
                  type="button"
                  className={s.consoleToggle()}
                  aria-expanded={consoleOpen}
                  aria-controls={consoleBodyId}
                  onClick={() => setConsoleOpen(!consoleOpen)}
                >
                  <ChevronDown size={14} aria-hidden className={s.consoleChevron()} />
                  {consoleLabel}
                </button>
                {consoleActions != null && <div className={s.consoleActions()}>{consoleActions}</div>}
              </div>
              <div id={consoleBodyId} hidden={!consoleOpen} className={s.consoleBody()}>
                {consoleContent}
              </div>
            </section>
          )}
        </div>
        {inspector != null && (
          <aside id={inspectorId} aria-label={inspectorLabel} hidden={!inspectorOpen} className={s.inspector()}>
            <div className={s.panelTitle()} aria-hidden>
              {inspectorLabel}
            </div>
            <div className={s.panelBody()}>{inspector}</div>
          </aside>
        )}
      </div>
    </div>
  );
}

import { tv, type VariantProps } from '../../utils/tv';

export const canvasLayoutVariants = tv({
  slots: {
    root: 'relative flex flex-col overflow-hidden bg-background font-sans text-foreground',
    skipLink: 'focus:absolute',
    header: 'flex h-12 shrink-0 items-center gap-3 border-b border-border bg-chrome px-3',
    headerContent: 'flex min-w-0 flex-1 items-center gap-3',
    toggles: 'hidden shrink-0 items-center gap-1 lg:flex',
    body: 'flex min-h-0 flex-1',
    palette: 'hidden w-60 shrink-0 flex-col overflow-y-auto border-e border-border bg-card lg:flex',
    inspector: 'hidden w-72 shrink-0 flex-col overflow-y-auto border-s border-border bg-card lg:flex',
    panelTitle: 'flex h-10 shrink-0 items-center border-b border-border px-3 font-mono text-[10.5px] font-semibold tracking-[0.14em] text-muted-foreground uppercase',
    panelBody: 'flex-1 p-3',
    center: 'flex min-w-0 flex-1 flex-col',
    main: 'relative min-h-0 flex-1 overflow-hidden outline-none',
    notice: [
      'absolute top-3 left-1/2 z-20 flex max-w-[calc(100%-1.5rem)] -translate-x-1/2 items-center gap-2 lg:hidden',
      'rounded-md border border-border bg-card px-3 py-2 text-[12.5px] text-muted-foreground shadow-sm',
    ],
    toolbar: 'absolute top-3 left-1/2 z-10 hidden -translate-x-1/2 lg:block',
    console: 'flex shrink-0 flex-col border-t border-border bg-card',
    consoleBar: 'flex h-9 shrink-0 items-center gap-2 px-2',
    consoleToggle: [
      'inline-flex h-7 items-center gap-1.5 rounded-md px-2 font-mono text-[10.5px] font-semibold tracking-[0.14em] text-muted-foreground uppercase',
      'transition-colors hover:bg-secondary hover:text-foreground motion-reduce:transition-none',
      'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring',
    ],
    consoleChevron: 'transition-transform motion-reduce:transition-none',
    consoleActions: 'ms-auto flex items-center gap-1',
    consoleBody: 'h-40 overflow-y-auto border-t border-border font-mono text-[12px]',
  },
  variants: {
    fullScreen: {
      true: { root: 'h-dvh' },
      false: { root: 'h-full min-h-full' },
    },
    consoleOpen: {
      true: { consoleChevron: 'rotate-0' },
      false: { consoleChevron: '-rotate-90' },
    },
  },
  defaultVariants: { fullScreen: false, consoleOpen: true },
});

export type CanvasLayoutVariantProps = VariantProps<typeof canvasLayoutVariants>;

export { CanvasLayout, type CanvasLayoutProps } from './CanvasLayout';
export { canvasLayoutVariants, type CanvasLayoutVariantProps } from './canvas-layout.variants';
export { doc as canvasLayoutDoc } from './CanvasLayout.doc';

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'CanvasLayout',
  group: 'Layout',
  status: 'beta',
  description:
    'Editor shell for a full-bleed canvas (flow editor, code editor, map): top bar · left palette · canvas with a floating toolbar · right inspector · collapsible bottom console. Palette and inspector toggle from the top bar; each panel is controllable (`paletteOpen`, `inspectorOpen`, `consoleOpen`). Below `lg` the side panels and toggles hide and a read-only notice ("Open on a larger screen to edit") shows over the canvas. Fills its container; `fullScreen` switches to `h-dvh`.',
  pattern: 'landmarks (header, main, two labelled asides, labelled console region) + disclosure buttons',
  keyboard: [
    ['Tab', 'Skip link first, then the top bar, the panel toggles, the palette, the canvas, the console and the inspector'],
    ['Enter / Space on a panel toggle', 'Shows or hides the palette or inspector (aria-expanded reflects the state)'],
    ['Enter / Space on the console bar', 'Collapses or expands the console (aria-expanded)'],
  ],
  tokens: ['background', 'foreground', 'chrome', 'card', 'border', 'secondary', 'muted-foreground', 'focus-ring'],
};
